        return true;
    }
    // Create a set of common separator characters
    HashSet<Character> separators = new HashSet<>();
    separators.add(';');  // Example separator: comma
    separators.add('=');  // Example separator: equal sign
    separators.add('-');  // Example separator: hyphen
    // Check if the character is in the set of separators
    return separators.contains(c);
}

