private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    List<V> verticesList = new ArrayList<>(vertices);
    int n = verticesList.size();
    int[][] adjMatrix = new int[n][n];

    // Build the adjacency matrix
    for (V vertex : verticesList) {
        for (V neighbour : verticesList) {
            adjMatrix[verticesList.indexOf(vertex)][verticesList.indexOf(neighbour)] = edgeExists(graph, vertex, neighbour);
        }
    }

    // Check if the adjacency matrix is all 1's
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (i != j && adjMatrix[i][j] != 1) {
                return false;
            }
        }
    }
    return true;
}

