private void pop(final String descriptor) {
    int type = OpCode.OPVARINT;
    int argLength = 1;

    // Process the descriptor
    if (descriptor.startsWith("L")) {
        type = OpCode.OPCLASS; // If it's a class, process it as a reference type
        argLength = 5;
    } else if (descriptor.startsWith("[")) {
        type = OpCode.OPARRAY; // If it's an array, process it as an array
        argLength = 3;
    } else {
        type = OpCode.OPVARIABLE; // If it's an abstract type, process it as a variable
    }

    // Push the popped type onto the output frame stack
    outputFrameStack.push(type);
    outputFrameStack.push(argLength);
}

